package blockbranch.realistic;
import blockbranch.Blockbranch;
import blockbranch.cubic.*;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.item.*;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.levelgen.*;

/** Temperate marine identity and native light,water,kelp,immutable profiles and persisted edits. */
public final class OceanSmoke {
 private static final Map<DrainageNetwork,BlockPos> FIXTURE=Collections.synchronizedMap(new WeakHashMap<>());
 public static BlockPos fixture(RealisticGenerator g,RandomState r){return FIXTURE.computeIfAbsent(g.drainage(r),d->{var p=blockbranch.realistic.TemperateOceanFixtures.fixture(d,r.seed());return new BlockPos(p.x(),d.sample(p.x(),p.z()).height(),p.z());});}
 public static int height(RealisticGenerator g,RandomState r,BlockPos bed){return TemperateOcean.kelpHeight(r.seed(),bed.getX(),bed.getZ(),g.drainage(r),new ClimateField(r.seed()));}
 public static void restore(ServerLevel level,BlockPos bed){var base=((SparseColumn)level.getChunkAt(bed)).blockbranch$terrain().base();for(int y=bed.getY();y<TerrainShape.SEA_LEVEL;y++)level.setBlock(new BlockPos(bed.getX(),y,bed.getZ()),base.state(bed.getX(),y,bed.getZ()),2);}
 public static void grow(ServerLevel level,RealisticGenerator g,BlockPos bed){var r=level.getChunkSource().randomState();var tip=bed.above(height(g,r,bed));var state=level.getBlockState(tip);var plant=(BonemealableBlock)Blocks.KELP;require(plant.isValidBonemealTarget(level,tip,state,BonemealSource.INTERACTION),"Existing source water provides real kelp growth room");plant.performBonemeal(level,level.getRandom(),tip,state,BonemealSource.INTERACTION);}
 public static void removeSupport(ServerLevel level,RealisticGenerator g,BlockPos bed){level.setBlock(bed,Blocks.WATER.defaultBlockState(),3);for(int y=1;y<=height(g,level.getChunkSource().randomState(),bed)+1;y++){var p=bed.above(y);level.getBlockState(p).tick(level,p,level.getRandom());}}
 public static void verify(ServerLevel level,RealisticGenerator g,boolean reload){var r=level.getChunkSource().randomState();var d=g.drainage(r);var bed=fixture(g,r);int h=height(g,r,bed);var tip=bed.above(h);var saved=bed.below(8);if(reload){require(level.getBlockState(saved).is(Blocks.CLAY),"Saved temperate bed edit");require(level.getBlockState(tip).is(Blocks.KELP)&&level.getBlockState(tip).getValue(GrowingPlantHeadBlock.AGE)==25,"Saved native head age");}restore(level,bed);
 var lightFence=level.getChunkSource().getLightEngine().waitForPendingTasks(bed.getX()>>4,bed.getZ()>>4);level.getServer().managedBlock(lightFence::isDone);lightFence.join();
 require(level.getBiome(bed).is(net.minecraft.world.level.biome.Biomes.OCEAN),"Actual vanilla Ocean identity");require(level.getBrightness(LightLayer.SKY,bed.above())>=5,"Native daylight reaches generated kelp base");int plants=0,heads=0;
 for(int cz=(bed.getZ()>>4)-1;cz<=(bed.getZ()>>4)+1;cz++)for(int cx=(bed.getX()>>4)-1;cx<=(bed.getX()>>4)+1;cx++){var chunk=level.getChunk(cx,cz);var base=((SparseColumn)chunk).blockbranch$terrain().base();var tag=base.encode(level.palettedContainerFactory());var copy=TerrainProfile.decode(tag,level.palettedContainerFactory());var sections=new HashMap<Integer,net.minecraft.world.level.chunk.LevelChunkSection>();
  for(int v:base.canopy().encode()){int key=v>>>blockbranch.cubic.CanopyLayer.STATE_BITS,x=cx*16+(key&15),z=cz*16+((key>>>4)&15),y=(key>>>8)+TerrainShape.FLOOR,code=v&blockbranch.cubic.CanopyLayer.STATE_MASK;if(code<89)continue;plants++;var p=new BlockPos(x,y,z);var state=level.getBlockState(p);require(state==copy.state(x,y,z)&&state==g.surfaceState(x,y,z,r)&&state==sections.computeIfAbsent(y>>4,copy::generate).getBlockState(x&15,y&15,z&15),"Native/saved/client kelp state agreement");require(state.canSurvive(level,p)&&state.getFluidState().isSource(),"Actual kelp support and retained source water");var s=MarineShelf.site(d,x,z);require(s.depth()>=4&&s.depth()<=10&&y<s.water()&&s.slope()<=.18,"Conservative exact photic/support domain");if(code==90){heads++;require(base.randomTickSections().contains(y>>4)&&state.isRandomlyTicking(),"Actual ticking kelp heads");}}
  for(int z=0;z<16;z+=4)for(int x=0;x<16;x+=4){int wx=cx*16+x,wz=cz*16+z;var s=d.sample(wx,wz);for(int y=s.height()-3;y<=s.waterLevel()+1;y++){var p=new BlockPos(wx,y,wz);require(level.getBlockState(p)==g.surfaceState(wx,y,wz,r)&&copy.state(wx,y,wz)==g.surfaceState(wx,y,wz,r),"Bed/vegetation/fluid native and profile agreement");if(y>s.height()&&y<s.waterLevel())require(level.getFluidState(p).isSource(),"Ocean source-water column retained");}for(var type:Heightmap.Types.values()){int actual=chunk.getHeight(type,x,z)+1,analytic=g.getBaseHeight(wx,wz,type,level,r);require(actual==analytic,"All native Ocean heightmaps "+type+" at "+wx+","+wz+" actual="+actual+" analytic="+analytic);for(var bounds:new LevelHeightAccessor[]{LevelHeightAccessor.create(s.height()-2,3),LevelHeightAccessor.create(s.height()+1,3),LevelHeightAccessor.create(s.waterLevel()-2,3),LevelHeightAccessor.create(s.waterLevel()+1,3)}){var column=g.getBaseColumn(wx,wz,bounds,r);int expected=bounds.getMinY();for(int y=bounds.getMaxY();y>=bounds.getMinY();y--)if(type.isOpaque().test(column.getBlock(y))){expected=y+1;break;}require(g.getBaseHeight(wx,wz,type,bounds,r)==expected,"Clipped submerged-overlay height query "+type);}}for(int qy:new int[]{-3000,0,2000})require(chunk.getNoiseBiome(wx>>2,qy,wz>>2).equals(g.getBiomeSource().createUncachedResolver(r).getNoiseBiome(wx>>2,qy,wz>>2)),"All-altitude identity agrees with source");}
  var a=tag.getIntArray("canopy").orElseThrow();if(a.length>0){int original=base.canopy().encode()[0];a[0]=0;require(base.canopy().encode()[0]==original,"Kelp serialized snapshot isolation");}
 }
 require(heads>5&&plants>20,"Actual nontrivial natural kelp colonies");var original=level.getBlockState(tip);require(Block.getDrops(original,level,tip,null,null,ItemStack.EMPTY).stream().anyMatch(s->s.is(Items.KELP)),"Existing usable vanilla kelp item");grow(level,g,bed);require(level.getBlockState(tip).is(Blocks.KELP_PLANT)&&level.getBlockState(tip.above()).is(Blocks.KELP)&&level.getFluidState(tip.above()).isSource(),"Native head grows one block and leaves waterlogged body");restore(level,bed);removeSupport(level,g,bed);for(int y=1;y<=h;y++)require(level.getBlockState(bed.above(y)).is(Blocks.WATER),"Unsupported kelp yields source water");restore(level,bed);
 var terrain=((SparseColumn)level.getChunkAt(bed)).blockbranch$terrain();level.setBlock(tip,original.setValue(GrowingPlantHeadBlock.AGE,25),2);level.setBlock(saved,Blocks.CLAY.defaultBlockState(),2);level.getChunkAt(bed).markUnsaved();terrain.flush();terrain.evictOutside(-100,-90);require(level.getBlockState(tip).getValue(GrowingPlantHeadBlock.AGE)==25&&level.getBlockState(saved).is(Blocks.CLAY),"Native head age and bed edits survive lazy eviction");Blockbranch.LOGGER.info("TEMPERATE_OCEAN_NATIVE_PASS {} bed={} depth={} heads={} kelpBlocks={}",reload?"RELOAD":"NEW",bed,TerrainShape.SEA_LEVEL-bed.getY()-1,heads,plants);
 }
 private static void require(boolean b,String m){if(!b)throw new AssertionError(m);}
 private OceanSmoke(){}
}
